css:
/* Dois botões lado a lado; no celular eles empilham junto com o .amb-btn
   virando largura cheia. */
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
@media (max-width: 520px) { .hero-actions { flex-direction: column; } }

.amb-btn {
  --amb-shadow: rgba(14, 165, 233, 0.35);
  position: relative;
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  width: auto; min-width: 0; padding: 16px 28px;
  font-family: 'JetBrains Mono', monospace; font-size: 12px; font-weight: 600;
  letter-spacing: 0.08em; text-transform: uppercase; white-space: nowrap;
  color: var(--bg);
  background: linear-gradient(135deg, var(--amb-from), var(--amb-to));
  border: 1px solid transparent; border-radius: 4px;
  overflow: hidden; cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.25);
  transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease, background-color 0.2s ease;
}

/* textura fosca (grão), no lugar do brilho/reflexo de um botão "metálico" */
.amb-btn::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background-image: radial-gradient(circle, var(--amb-dot) 1px, transparent 1.4px);
  background-size: 6px 6px;
  opacity: 0.08;
}

/* Glifo de pontinhos (dois chevrons). */
.amb-dot { position: relative; flex-shrink: 0; overflow: visible; }
.amb-dot circle {
  fill: var(--amb-dot);
  transform-box: fill-box; transform-origin: center;
  animation: amb-dot-wave 1.4s ease-in-out infinite;
}
/* A onda percorre os dois chevrons de cima para baixo. */
.amb-dot circle:nth-child(1) { animation-delay: 0s; }
.amb-dot circle:nth-child(2), .amb-dot circle:nth-child(6) { animation-delay: 0.05s; }
.amb-dot circle:nth-child(3), .amb-dot circle:nth-child(7) { animation-delay: 0.10s; }
.amb-dot circle:nth-child(4), .amb-dot circle:nth-child(8) { animation-delay: 0.15s; }
.amb-dot circle:nth-child(5), .amb-dot circle:nth-child(9) { animation-delay: 0.20s; }
.amb-dot circle:nth-child(10) { animation-delay: 0.25s; }

.amb-label { position: relative; display: inline-flex; align-items: center; gap: 10px; }

.amb-btn:hover { transform: translateY(-2px); box-shadow: inset 0 1px 0 rgba(255,255,255,0.25), 0 10px 24px -8px var(--amb-shadow); }
.amb-btn:active { transform: translateY(0); }

/* Quase todo botão é um <a>, e o `a:hover { color: var(--accent-hover) }` do
   base.css vence .amb-btn na especificidade — o texto virava azul claro em
   cima do azul do botão. No hover o texto é branco. */
.amb-btn:hover, .amb-btn:hover .amb-label { color: #fff; }

/* variante secundária/outline — mantém a hierarquia visual quando há dois botões lado a lado */
.amb-btn[data-variant="outline"] {
  color: #fff; background: transparent; border-color: #333;
  box-shadow: none;
}
.amb-btn[data-variant="outline"]::after { opacity: 0; transition: opacity 0.2s ease; }
.amb-btn[data-variant="outline"] .amb-dot circle { fill: var(--amb-from); }
.amb-btn[data-variant="outline"]:hover {
  color: #fff; background: linear-gradient(135deg, var(--amb-from), var(--amb-to)); border-color: transparent;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.25), 0 10px 24px -8px var(--amb-shadow);
}
.amb-btn[data-variant="outline"]:hover::after { opacity: 0.08; }
.amb-btn[data-variant="outline"]:hover .amb-dot circle { fill: var(--amb-dot); }

@keyframes amb-dot-wave {
  0%, 70%, 100% { opacity: 0.25; transform: scale(0.85); }
  35% { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .amb-dot circle { animation: none; opacity: 1; }
}

@media (max-width: 520px) {
  .amb-btn { width: 100%; }
}

js:
// Aprimora progressivamente qualquer elemento com a classe "amb-btn":
// injeta o glifo de pontinhos e envolve o texto num <span class="amb-label">,
// preservando ícones/spans internos já existentes (ex: a seta do CTA).

// Os dez pontos formam dois chevrons ">>".
const DOT_POSITIONS = [
  [2, 2], [5, 5], [8, 8], [5, 11], [2, 14],
  [6, 2], [9, 5], [12, 8], [9, 11], [6, 14]
];

const DOT_SVG =
  '<svg class="amb-dot" width="14" height="16" viewBox="0 0 14 16" aria-hidden="true" focusable="false">' +
  DOT_POSITIONS.map(function (p) {
    return '<circle cx="' + p[0] + '" cy="' + p[1] + '" r="1"/>';
  }).join('') +
  '</svg>';

export function initAntiMetalButtons(root) {
  const scope = root || document;
  scope.querySelectorAll('.amb-btn').forEach(function (el) {
    if (el.dataset.ambReady) return;
    el.dataset.ambReady = 'true';

    const label = document.createElement('span');
    label.className = 'amb-label';
    while (el.firstChild) {
      label.appendChild(el.firstChild);
    }

    el.insertAdjacentHTML('beforeend', DOT_SVG);
    el.appendChild(label);
  });
}
